const sze = 20;
let minDist, maxDist;
let spots;
// https://www.flagcolorcodes.com/pride-rainbow
const CLRS = ["#E40303", "#FF8C00", "#FFED00", "#008026", "#004CFF", "#732982"]

function setup() {
	createCanvas(S=max(windowWidth, windowHeight), S);
	describe("animation of radial pride flag with altering dots color intensity per noise")
	pixelDensity(1);
	minDist = max(width, height) / 2;
	maxDist = sqrt(width * width + height * height);
	background(255);
	// colorMode(HSB);

	spots = [];
	spots.push({x: 0, y: 0});
	for (let i = 0; i < 3; i++) {
		const x = random(-width * 0.4, width * 0.4);
		const y = random(-height * 0.4, height * 0.4);
		spots.push({x, y});
	}
}

function windowResized() {
	setup();
}

function draw() {
	background(255);
	translate(width * 0.5, height * 0.5)

	const numClrRange = 6;
	const minSpots = minDist/sze - 2; // 2 extra 
	const maxSpots = maxDist/sze;
	for (let sector = 0; sector < maxSpots; sector++) {
		const amount = max(1, sector * 7);
		for (let angle = 0; angle < TWO_PI; angle+=TWO_PI/amount) {
			// const sector = floor(random(max(width, height) / sze ));
			// const angle = floor(random(amount)) * TWO_PI / amount;
			var x = cos(angle) * sector * sze
			var y = sin(angle) * sector * sze
			let weight = map(x + y, -maxDist, maxDist, -sze * 0.15, sze)
			// weight += noise((x + frameCount * 0.1) * 0.01, (y + frameCount * 0.2) * 0.02) * sze * 0.5 - sze * 0.25
			weight += noise(x * 0.01, y * 0.02, frameCount * 0.1) * sze * 0.5 - sze * 0.25
			if (weight > 0.5) {
				// const hue = ~~(sector / minSpots * numClrRange) * 360 / numClrRange;
				// stroke(color(hue, 75, 50));
				if (sector > minSpots) {
					stroke("rgb(203,211,214)")
				} else {
					const ci = ~~(sector / minSpots * numClrRange);
					stroke(CLRS[ci]);
				}
				strokeWeight(weight * 1.5);
				point(x, y)
			}
		}
	}

}

// not in use per now
function drawRandomPointsPerFrame() {
	translate(width * 0.5, height * 0.5)
	const spot = random(spots)
	translate(spot.x, spot.y)

	for (let i = 0; i < 10; i++) {
		const sector = floor(random(max(width, height) / sze ));
		var amount = max(1, sector * 7);
		const angle = floor(random(amount)) * TWO_PI / amount;
		var x = cos(angle) * sector * sze
		var y = sin(angle) * sector * sze
		var weight = map(x + y, -maxDist, maxDist, -sze * 0.5, sze)
		weight += noise(x * 0.01, y * 0.02) * sze * 0.5 - sze * 0.25
		if (weight > 0.5) {
			strokeWeight(weight * 2);
			point(x, y)
		}
	}
}
